import{z as B,x as o,o as r,c as p,q as n,j as s,D as e,d as t,s as i,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"缺口风险 gap risk","description":"","frontmatter":{"title":"缺口风险 gap risk","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gap-risk.md","filePath":"quant/gap-risk.md","lastUpdated":1791063341000}'),m={name:"quant/gap-risk.md"};function d(g,a,D,h,u,S){const l=o("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="缺口风险-gap-risk" tabindex="-1">缺口风险 gap risk <a class="header-anchor" href="#缺口风险-gap-risk" aria-label="Permalink to &quot;缺口风险 gap risk&quot;">​</a></h1><div class="epigraph"><p>连续对冲假定你能在路径的每一点再平衡；价格若在不可交易的间隔里跳过执行价、障碍或 CPPI 的债券底，损益在开盘时一次性实现，加密日内 Delta 消灭不了这一跳。</p><footer>—— 离散复制误差见 Boyle and Emanuel, 1980；跳扩散见 Merton, 1976；障碍监控与缺口是结构化产品风险的标准对象</footer></div><p><a href="/quant/span-simm">上一课</a>表明 SPAN 用价格–波动网格的最大损失服务清算 IM，SIMM 用公开参数的敏感性加总服务非清算 IM；网格外缺口与希腊字母抓不住的奇异风险，两套都会漏。缺口是不可交易间隔里的离散跳。连续对冲与扩散 VaR 把障碍、CPPI 底、自动赎回写成平滑路径上的分位数，中间没有报价的 \\(\\Delta S\\) 可以跨过非线性阈值。本课把 gap risk 写成必须单独建模的一项。不重讲扫描档位。后课拥挤螺旋默认已经读完：集中在同一障碍附近的名义应合并计量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续模型里，局部风险由 Delta、Gamma、Vega 描述，小移动用泰勒展开。缺口 \\(\\Delta S\\) 可以是数个标准差且中间没有报价，泰勒在障碍点不成立：\\(g(S)\\) 在障碍 \\(B\\) 处不连续或导数爆炸。典型结构：</p><ul><li><strong>障碍期权：</strong> 向下敲入若跳过 \\(B\\)，从零变成深度价内，空头瞬间出现 Delta 与负值。离散监控与连续监控的差别见障碍监控类工作；缺口使「收盘未破、盘中已破」或「隔夜已破」成为定价与对冲的核心。</li><li><strong>CPPI / 组合保险：</strong> 乘数把仓位钉在 \\(m\\times\\) 垫头上。缺口若一次打穿债券底，理论应已降到零风险资产，实际来不及卖，剩余是股票缺口损失。这是缺口风险的经典银行定义之一。</li><li><strong>自动赎回 / 反向可转：</strong> 观察日开盘相对敲入价的跳，决定是否变成股票交割。</li></ul><p>问题是：扩散 VaR 把这些事件的概率估成几乎为零（正态一日 5% 跳的尾极薄），而真实缺口来自隔夜信息、停牌后复牌、宏观发布。必须用跳过程、压力情景或隔夜经验分布，而不是加密 GARCH 的 \\(\\Delta t\\)。</p><h3 id="缺口不是「很大的日内波动」" tabindex="-1">缺口不是「很大的日内波动」 <a class="header-anchor" href="#缺口不是「很大的日内波动」" aria-label="Permalink to &quot;缺口不是「很大的日内波动」&quot;">​</a></h3><p>把隔夜收益塞进五分钟已实现波动的第一格，等于假设跳来自同一扩散。French 等对隔夜与周末的研究说明非交易间隔的方差率与交易时段不同。停牌再开是制度性缺口，见 <a href="/quant/trading-halts">停牌</a>。涨跌停把连续路径截断，打开时一次补完，对障碍是另一种监控。风控若只用交易时段的 \\(\\sigma\\) 乘日历小时数，会系统低估缺口。</p><p><span class="marginnote">缺口风险的资本若用「99% 日 VaR 乘一个倍数」，倍数永远说不清。应单独定义缺口损失 \\(L_{\\mathrm{gap}}=g(S_{t+}\\Delta)-g(S_t)\\)，其中 \\(S_{t+}\\) 来自跳情景，再对 \\(L_{\\mathrm{gap}}\\) 取压力或跳测度下的分位数 / ES。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>跳情景表。</strong> 对每个非线性阈值（执行价、障碍、CPPI 底、自动赎回触发），列出：隔夜历史分位数跳、周末跳、该标的停牌复牌跳、指数期货可交易而现货不可交易的基差跳。</p><p><span class="marginnote">CPPI 缺口的数字实例：垫头 6%、乘数 4，风险资产占 \\(4\\times 6\\%=24\\%\\)。一夜跳 \\(-12\\%\\)，损失 \\(24\\%\\times 12\\%=2.88\\%\\)，垫头还接得住；若跳 \\(-30\\%\\)，损失 \\(7.2\\%\\) 超过垫头 6%，债券底被击穿——而开盘那一刻你无法卖出。缓冲设多大，就是把「历史最大隔夜跳」代进这道乘法。</span>每个情景全定价，得到 \\(L_{\\mathrm{gap}}\\)。限额写成：给定情景集合上 \\(\\max L_{\\mathrm{gap}}\\) 或概率加权 ES 不得超过预算。这与 SPAN 网格同类，但情景必须对准<strong>你的阈值</strong>，而不是交易所通用的价格档。</p><p><strong>跳扩散 / 方差伽马。</strong> Merton 跳扩散给 \\(\\Delta S\\) 一个强度为 \\(\\lambda\\) 的复合泊松。VaR/ES 在含跳的预测分布上计算，缺口产品的 \\(g\\) 用全定价。校准应区分交易时段跳与隔夜跳；用日内高频估 \\(\\lambda\\) 再用于隔夜，强度会错。 Bates 一类随机波动加跳，对同时「波动跳起 + 现货跳下」的缺口更诚实。模型风险大，应与情景表并行，而不是替代。</p><p><strong>监控约定。</strong> 连续监控、收盘监控、盘中障碍，三种 \\(g\\) 不同。</p><p><span class="marginnote">常见误区：拿定价库的默认监控当合同条款。合同写收盘监控，隔夜跳到障碍下方，要到收盘才「正式」敲入，开盘到收盘之间你已裸露却还没触发；合同写连续监控，跳过即刻敲定。同一条价格路径，两种约定给出不同的敲入时点与不同的对冲裸露时长——风险系统必须读合同，不能用模型默认。</span></p>',16)),(r(),s(A,null,{default:e(()=>[i(l,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%88%97%E5%87%BA%E5%85%A8%E9%83%A8%E9%9D%9E%E7%BA%BF%E6%80%A7%E9%98%88%E5%80%BC%EF%BC%9A%E9%9A%9C%E7%A2%8D%2F%E6%89%A7%E8%A1%8C%E4%BB%B7%2FCPPI%20%E5%BA%95%2F%E8%B5%8E%E5%9B%9E%E8%A7%A6%E5%8F%91%22%5D%20--%3E%20S1%5B%22%E9%9A%94%E5%A4%9C%E4%B8%8E%E5%91%A8%E6%9C%AB%E5%8E%86%E5%8F%B2%E5%88%86%E4%BD%8D%E8%B7%B3%22%5D%0A%20%20T%20--%3E%20S2%5B%22%E5%81%9C%E7%89%8C%E5%A4%8D%E7%89%8C%E8%B7%B3%22%5D%0A%20%20T%20--%3E%20S3%5B%22%E6%9C%9F%E8%B4%A7%E5%8F%AF%E4%BA%A4%E6%98%93%E3%80%81%E7%8E%B0%E8%B4%A7%E4%B8%8D%E5%8F%AF%E4%BA%A4%E6%98%93%E7%9A%84%E5%9F%BA%E5%B7%AE%E8%B7%B3%22%5D%0A%20%20S1%20--%3E%20P%5B%22%E6%AF%8F%E4%B8%AA%E6%83%85%E6%99%AF%E5%85%A8%E5%AE%9A%E4%BB%B7%20%E2%86%92%20L_gap%22%5D%0A%20%20S2%20--%3E%20P%0A%20%20S3%20--%3E%20P%0A%20%20P%20--%3E%20L%5B%22%E9%99%90%E9%A2%9D%EF%BC%9A%E6%83%85%E6%99%AF%E9%9B%86%E4%B8%8A%20max%20L_gap%20%E6%88%96%E5%8A%A0%E6%9D%83%20ES%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>合同写收盘监控，隔夜跳只在次日收盘才决定敲入，缺口时点延后，但开盘到收盘仍可能无法对冲已裸露的 Delta。合同写美式障碍，隔夜已经敲定。风险系统必须读合同，不能用定价库默认监控。离散监控的缺口与连续极限不是同一价格，对冲比也不能共用。</p><h3 id="与-var、保证金的接口" tabindex="-1">与 VaR、保证金的接口 <a class="header-anchor" href="#与-var、保证金的接口" aria-label="Permalink to &quot;与 VaR、保证金的接口&quot;">​</a></h3><p>日常 FHS 若残差来自含隔夜的日收益，会把一部分历史缺口带进经验测度，但样本里没有的跳幅仍不会出现。压力期 <a href="/quant/stressed-var-frtb">FRTB</a> 可能含 2008 年的隔夜跳，对当前障碍位置不必是最坏：最坏是「从当前 \\(S\\) 刚好跳过 \\(B\\)」的那一档。因此缺口限额不能并入压力 ES 了事，要对准距离阈值的几何。SPAN/SIMM 对奇异障碍覆盖不足，发行台应有独立缺口资本，而不是指望初始保证金。</p><p>对冲政策：收盘前把净 Gamma、净障碍暴露压到跳情景可接受；用虚值保护转移缺口，而不是更勤的日内 Delta。CPPI 应设缺口缓冲（乘数上限、垫头下限），使历史最大隔夜跳仍留在债券底之上。缓冲吃收益，那是保费。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缺口的机制是状态变量在不可交易集合上的不连续更新。复制论要求的可交易区间被挖掉一块，伊藤公式的 \\(dt\\) 项与 \\(\\mathrm{d}S\\) 项中间插入 \\(\\Delta S\\)。Gamma 损失 \\(\\tfrac12\\Gamma(\\Delta S)^2\\) 是光滑 \\(g\\) 的二次近似；\\(g\\) 有跳跃时，损失是 \\(g(S+\\Delta S)-g(S)-\\Delta\\cdot\\Delta S\\)，可以接近整个期权名义。尾依赖使多标的篮子同时跳，篮子障碍比单名更脆。这是 <a href="/quant/copula-var">Copula</a> 的缺口版本：边缘跳加上同跳。</p><p>内生缺口：你的对冲在开盘拍卖上成为冲击，触发更多障碍，见流动性螺旋。</p><p><span class="marginnote">术语翻译：「内生缺口」指价格跳的部分原因是你自己的交易——发行台开盘抛对冲，砸穿别人的障碍，触发更多对冲抛售，像银行挤兑：每个储户单独看都理性，合力却制造了挤兑本身。风险模型把 \\(\\Delta S\\) 当外生（天灾），会系统性低估这种「人祸」成分，所以同一障碍附近的名义必须合并计量。</span>风险模型若把 \\(\\Delta S\\) 当外生，会低估发行规模大的结构化产品在敲入潮中的损失。限额因此要含集中度：同一障碍附近的名义之和，而不是各账户单独的缺口 ES 相加——相加会假分散。</p><p><span class="marginnote">A 股 T+1、涨跌停、指数与个股不同步开盘，使「用期货补隔夜 Delta」留下基差缺口。缺口清单必须按交易制度分市场，不能从美股复制粘贴。</span></p><h3 id="估计-样本不够时用几何而不是频率" tabindex="-1">估计：样本不够时用几何而不是频率 <a class="header-anchor" href="#估计-样本不够时用几何而不是频率" aria-label="Permalink to &quot;估计：样本不够时用几何而不是频率&quot;">​</a></h3><p>个股 5% 隔夜跳可能十年一遇，障碍产品的样本 ES 几乎不可估。此时用几何：当前距离障碍的百分比，对照该标的与同类标的的历史最大缺口、指数缺口、停牌缺口。频率模型（\\(\\lambda\\)）用指数或行业估计，幅度用压力表。EVT 对日损失的 GPD 含一部分缺口日，但混合了连续尾与跳；若关心合同阈值，应把跳日单独建样本。回测缺口模型不要用 Kupiec 对日 VaR：缺口事件太稀，应做情景覆盖（是否含历史最大跳）与对新发产品的事前缓冲检查。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缺口风险不是把置信水平从 99% 调到 99.9%。更高 \\(\\alpha\\) 仍在同一扩散测度里外推，除非测度含跳。也不要与 pin 混用：pin 是到期日在 \\(K\\) 附近的二元，缺口是任意时刻的离散跳。两者在到期周重叠，政策可以合并，定义不要合并。模型方面，纯扩散 + 短 \\(\\Delta t\\) 的 MC 会漏掉隔夜；必须显式插入非交易间隔。</p><p>发行与做市的利益冲突：发行台卖出缺口（客户买保护或买收益率），簿上留下跳的空头。VaR 限额按扩散可能显示安全。治理上缺口 ES 应有独立预算，突破则停发，而不是用更高的票息去「补偿」未对冲的跳。保证金（SPAN 网格）可能覆盖一部分，但网格档位不是你的障碍。</p><p><span class="marginnote">把缺口称为「操作风险（系统在隔夜没对冲）」会分错类。对冲本来就无法在间隔内发生。它是市场风险在不可交易时段的实现，资本应在市场风险里单列。</span></p>',15)),(r(),s(A,null,{default:e(()=>[i(l,{id:"mermaid-106",class:"mermaid",graph:"flowchart%20TD%0A%20%20Nt%5B%22%E4%B8%8D%E5%8F%AF%E4%BA%A4%E6%98%93%E9%97%B4%E9%9A%94%22%5D%20--%3E%20Jump%5B%22%E7%A6%BB%E6%95%A3%20%CE%94S%22%5D%0A%20%20Jump%20--%3E%20Bar%5B%22%E8%B7%A8%E8%B6%8A%E9%9A%9C%E7%A2%8D%20%2F%20%E6%89%A7%E8%A1%8C%E4%BB%B7%20%2F%20CPPI%20%E5%BA%95%22%5D%0A%20%20Bar%20--%3E%20Lg%5B%22%E7%BC%BA%E5%8F%A3%E6%8D%9F%E5%A4%B1%20L_gap%22%5D%0A%20%20Diff%5B%22%E6%89%A9%E6%95%A3%20VaR%22%5D%20--%3E%20Miss%5B%22%E5%87%A0%E4%B9%8E%E7%9C%8B%E4%B8%8D%E8%A7%81%E8%B7%B3%22%5D%0A%20%20Scen%5B%22%E5%AF%B9%E5%87%86%E9%98%88%E5%80%BC%E7%9A%84%E8%B7%B3%E6%83%85%E6%99%AF%22%5D%20--%3E%20Lg%0A%20%20Mert%5B%22%E8%B7%B3%E6%89%A9%E6%95%A3%20%2F%20%E5%8E%8B%E5%8A%9B%20ES%22%5D%20--%3E%20Lg%0A%20%20Lg%20--%3E%20Lim%5B%22%E7%8B%AC%E7%AB%8B%E7%BC%BA%E5%8F%A3%E9%99%90%E9%A2%9D%22%5D%0A%20%20Hed%5B%22%E6%94%B6%E7%9B%98%E5%87%8F%20Gamma%20%2F%20%E4%B9%B0%E4%BF%9D%E6%8A%A4%22%5D%20--%3E%20Red%5B%22%E7%BC%A9%E5%B0%8F%20L_gap%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"小结",tabindex:"-1"},[t("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=E("ul",null,[E("li",null,"缺口风险是不可交易间隔里的离散跳跨过非线性阈值，连续对冲与扩散 VaR 都覆盖不到。"),E("li",null,"应对准障碍、CPPI 底、自动赎回等几何位置建跳情景，并与历史隔夜、停牌复牌对照。"),E("li",null,"Merton 类跳过程可补概率，但不能替代对准当前阈值的压力表。"),E("li",null,"集中在同一障碍附近的名义应合并计量；分账户加总会假分散。"),E("li",null,[t("出处：Merton, "),E("em",null,"Journal of Financial Economics"),t(", 1976；Boyle and Emanuel, 1980；French 对非交易间隔；障碍与 CPPI 缺口为结构化产品风险管理的公开标准讨论；制度侧对照停牌与隔夜对冲实务。")])],-1))])}const C=B(m,[["render",d]]);export{c as __pageData,C as default};
